insert into public.articles (slug, title, title_ar, excerpt, excerpt_ar, image, date, author, content_html, content_ar)
values
  ('how-to-apply-bakhoor-at-home','How to Apply Bakhoor at Home Like a Pro','كيف تبخّر منزلك كالمحترفين','Charcoal, burners, ventilation — the ritual done right.','الفحم والمباخر والتهوية — الطقوس بالطريقة الصحيحة.','/theme-assets/comment-blog.jpg','2026-08-12','Misk Al Ghazaal','<p>Start with a quality charcoal disc, let it ash over, then place a single Jawhara tablet…</p><p>Ventilate lightly and move the mabkhara room to room for even scent.</p>','<p>ابدأ بقرص فحم جيد، دعه يتحول لرماد، ثم ضع قرص جوهرة واحداً…</p><p>هوِّ المكان قليلاً وحرّك المبخرة من غرفة لأخرى لتوزيع العبير.</p>'),
  ('misk-vs-musk-what-is-the-difference','Misk vs Musk: What Is the Difference?','المسك مقابل المسك: ما الفرق؟','Origins, scent profiles and how to choose.','الأصول وطبقات العطر وكيف تختار.','/theme-assets/comment-blog.jpg','2026-07-28','Misk Al Ghazaal','<p>Misk Al Ghazaal refers to a specific traditional blend…</p>','<p>يشير مسك الغزال إلى خلطة تقليدية محددة…</p>'),
  ('oudh-grades-hindi-vs-cambodi','Oudh Grades: Hindi vs Cambodi','درجات العود: الهندي مقابل الكمبودي','A connoisseur''s quick guide to pure dehn al oud.','دليل سريع لدهن العود الأصيل لعشاقه.','/theme-assets/comment-blog.jpg','2026-06-15','Misk Al Ghazaal','<p>Hindi oudh is deep and balsamic; Cambodi is sweeter…</p>','<p>العود الهندي عميق وبلسمي؛ والكمبودي أحلى…</p>')
