-- ============================================================================
-- Misk Al Ghazaal — full catalog seed (GENERATED once from the old
-- mock-data.ts, which has since been deleted — this file is now canonical).
-- Safe to re-run: collections/products/articles upsert on slug; variants,
-- links and banners are wiped + re-inserted for the seeded slugs/slots.
-- Run AFTER supabase/schema.sql.
-- ============================================================================

-- ------------------------------------------------------------ collections --
on conflict (slug) do update set
  title = excluded.title, title_ar = excluded.title_ar, image = excluded.image,
  description = excluded.description, description_ar = excluded.description_ar,
  sort = excluded.sort;

-- --------------------------------------------------------------- products --
on conflict (slug) do update set
  title = excluded.title, title_ar = excluded.title_ar,
  description_html = excluded.description_html, description_ar = excluded.description_ar,
  price = excluded.price, compare_at = excluded.compare_at, images = excluded.images,
  rating = excluded.rating, review_count = excluded.review_count,
  featured = excluded.featured, is_new = excluded.is_new,
  is_best_seller = excluded.is_best_seller, template = excluded.template;

-- --------------------------------------------------------------- variants --
delete from public.variants where product_id in (select id from public.products where slug in ('abukhalid','abukhalid-home-fragrance-150ml','ajayal','al-aqeedha-from-misk-al-ghazal-best-bakhoor','al-ghazaal-natural-perfume','al-qasar-oud-abyad-from-misk-al-ghazal-bakhoor-tablets','amber-oud-100ml-unisex','amber-wood','anfasic-al-ward','be-musky-100ml-unisex','classic-oud','diwaan-natural-perfume-for-men-and-women-success','dukhoon-eshq','dukhoon-misk-al-ghazaal','dukhoonak-big-boss','floral-garden-eau-de-parfum-100ml-for-women','gazaal-chancellor-edp-100ml','gazaal-my-wish-edp-100ml','golden-musk-100ml-unisex','grand-hall','hob-al-banaat','jawahara-from-misk-al-ghazal-bakhoor-tablets-arabic-insence','louvre','m05','misk-al-barari','misk-al-ghazaal-abukhalid-50ml','misk-al-hob','misk-al-khaleej','muattar-abu-khalifa','mubakhar-fayha','mubakhar-misk-al-khaleej','naajih-eau-de-parfum-100ml-unisex','no-7-zabeel-eau-de-parfum-100ml','noorjes-imagine','noorjes-luxury-le-don-ea-de-parfum-100ml','noorjes-luxury-star-times-edp-100ml','noorjes-maya-eau-de-parfum-100ml','noorjes-star-times-all-over-spray-100ml','opulence','petals','pink-bouquet','qasar-al-bustan-from-misk-al-ghazaal-bakhoor-tablets-incense','qasar-al-shiukh-from-misk-al-ghazal-bakhoor-tablets','sugar-wood','sulthan-variamkunnan-1921','the-legend-eau-de-parfum-100ml-unisex','white-mood-eau-de-parfum-100ml-unisex'));
;
-- -------------------------------------------------- product collections --
delete from public.product_collections where product_id in (select id from public.products where slug in ('abukhalid','abukhalid-home-fragrance-150ml','ajayal','al-aqeedha-from-misk-al-ghazal-best-bakhoor','al-ghazaal-natural-perfume','al-qasar-oud-abyad-from-misk-al-ghazal-bakhoor-tablets','amber-oud-100ml-unisex','amber-wood','anfasic-al-ward','be-musky-100ml-unisex','classic-oud','diwaan-natural-perfume-for-men-and-women-success','dukhoon-eshq','dukhoon-misk-al-ghazaal','dukhoonak-big-boss','floral-garden-eau-de-parfum-100ml-for-women','gazaal-chancellor-edp-100ml','gazaal-my-wish-edp-100ml','golden-musk-100ml-unisex','grand-hall','hob-al-banaat','jawahara-from-misk-al-ghazal-bakhoor-tablets-arabic-insence','louvre','m05','misk-al-barari','misk-al-ghazaal-abukhalid-50ml','misk-al-hob','misk-al-khaleej','muattar-abu-khalifa','mubakhar-fayha','mubakhar-misk-al-khaleej','naajih-eau-de-parfum-100ml-unisex','no-7-zabeel-eau-de-parfum-100ml','noorjes-imagine','noorjes-luxury-le-don-ea-de-parfum-100ml','noorjes-luxury-star-times-edp-100ml','noorjes-maya-eau-de-parfum-100ml','noorjes-star-times-all-over-spray-100ml','opulence','petals','pink-bouquet','qasar-al-bustan-from-misk-al-ghazaal-bakhoor-tablets-incense','qasar-al-shiukh-from-misk-al-ghazal-bakhoor-tablets','sugar-wood','sulthan-variamkunnan-1921','the-legend-eau-de-parfum-100ml-unisex','white-mood-eau-de-parfum-100ml-unisex'));
