-- ---------------------------------------------------------------- banners --
delete from public.banners where slot in ('hero','brand');
;
-- --------------------------------------------------------------- articles --
on conflict (slug) do update set
  title = excluded.title, title_ar = excluded.title_ar,
  excerpt = excluded.excerpt, excerpt_ar = excluded.excerpt_ar,
  image = excluded.image, date = excluded.date, author = excluded.author,
  content_html = excluded.content_html, content_ar = excluded.content_ar;

